<?php
declare(strict_types=1);
final class LifeFinanceMath {
 public static function amortization(float $principal,float $annual,int $months,int $earlyMonth=0,float $earlyAmount=0,float $fee=0):array{
  if(!is_finite($principal)||$principal<=0||$principal>1e10||!is_finite($annual)||$annual<0||$annual>1000||$months<1||$months>600||$earlyMonth<0||$earlyMonth>$months||$earlyAmount<0||$earlyAmount>$principal||$fee<0)throw new InvalidArgumentException(t('Check principal, rate, term and early-settlement values.'));
  $rate=$annual/1200;$original=(int)round($principal*100);$balance=$original;$payment=(int)round($rate>0?$original*$rate/(1-pow(1+$rate,-$months)):$original/$months);$interestTotal=0;$rows=[];$fees=0;
  if($earlyMonth===0&&$earlyAmount>0){$paid=min($balance,(int)round($earlyAmount*100));$balance-=$paid;if($balance===0)$fees=(int)round($fee*100);$rows[]=['month'=>0,'opening'=>$original/100.0,'interest'=>0,'payment'=>$paid/100.0,'closing'=>$balance/100.0,'fee'=>$fees/100.0];}
  for($i=1;$i<=$months&&$balance>0;$i++){$opening=$balance;$interest=(int)round($balance*$rate);$interestTotal+=$interest;$due=$balance+$interest;$normal=$i===$months?$due:min($due,$payment);$extra=$i===$earlyMonth?min(max(0,$due-$normal),(int)round($earlyAmount*100)):0;$paid=$normal+$extra;$balance=$due-$paid;$charge=0;if($balance===0&&$extra>0&&$i<$months){$charge=(int)round($fee*100);$fees+=$charge;}$rows[]=['month'=>$i,'opening'=>$opening/100.0,'interest'=>$interest/100.0,'payment'=>$paid/100.0,'closing'=>$balance/100.0,'fee'=>$charge/100.0];}
  return ['rows'=>$rows,'scheduled_payment'=>$payment/100.0,'interest'=>$interestTotal/100.0,'fees'=>$fees/100.0,'total'=>($original+$interestTotal+$fees-$balance)/100.0,'remaining'=>$balance/100.0,'months'=>count(array_filter($rows,fn($r)=>$r['month']>0))];
 }
 public static function debtPayoff(array $debts,float $extra,string $strategy):array{
  if(!in_array($strategy,['snowball','avalanche'],true)||$extra<0||$extra>1e10||count($debts)>100)throw new InvalidArgumentException(t('Choose a supported strategy, at most 100 debts and non-negative extra budget.'));$balances=[];$rates=[];$minimum=[];$budget=(int)round($extra*100);foreach($debts as $d){$id=(int)$d['id'];if($d['balance']<=0||$d['annual_rate']<0||$d['annual_rate']>1000||$d['minimum_payment']<=0)throw new InvalidArgumentException(t('Check debt balances, annual rates and minimum payments.'));$balances[$id]=(int)round($d['balance']*100);$rates[$id]=(float)$d['annual_rate']/1200;$minimum[$id]=(int)round($d['minimum_payment']*100);$budget+=$minimum[$id];}$initial=array_sum($balances);$interest=0;$rows=[];$paidOff=[];
  for($month=1;$month<=1200&&array_sum($balances)>0;$month++){$before=array_sum($balances);$monthlyInterest=0;foreach($balances as $id=>$balance)if($balance>0){$charge=(int)round($balance*$rates[$id]);$balances[$id]+=$charge;$interest+=$charge;$monthlyInterest+=$charge;}$remaining=$budget;$paid=0;foreach($balances as $id=>$balance){$pay=min($balance,$minimum[$id],$remaining);$balances[$id]-=$pay;$remaining-=$pay;$paid+=$pay;}$order=array_keys(array_filter($balances));usort($order,fn($a,$b)=>($strategy==='avalanche'?($rates[$b]<=>$rates[$a]):($balances[$a]<=>$balances[$b]))?:($a<=>$b));foreach($order as $id){$pay=min($balances[$id],$remaining);$balances[$id]-=$pay;$remaining-=$pay;$paid+=$pay;}foreach($balances as $id=>$balance)if($balance===0&&!isset($paidOff[$id]))$paidOff[$id]=$month;$rows[]=['month'=>$month,'interest'=>$monthlyInterest/100.0,'payment'=>$paid/100.0,'remaining'=>array_sum($balances)/100.0];if(array_sum($balances)>=$before&&$paid<=$monthlyInterest)break;}
  return ['paid_off'=>array_sum($balances)===0,'months'=>count($rows),'interest'=>$interest/100.0,'total'=>($initial+$interest-array_sum($balances))/100.0,'remaining'=>array_sum($balances)/100.0,'rows'=>$rows,'payoff_months'=>$paidOff,'monthly_budget'=>$budget/100.0];
 }
 public static function deposit(array $d):array{$days=(int)(new DateTimeImmutable($d['start_on']))->diff(new DateTimeImmutable($d['maturity_on']))->format('%r%a');if($days<=0)throw new InvalidArgumentException(t('Maturity must follow the start date.'));$principal=(float)$d['principal'];$r=(float)$d['rate']/100.0;if(($d['rate_type']??'annual')==='flat')$gross=$principal*$r;else $gross=match($d['compounding']??'simple'){'monthly'=>$principal*(pow(1+$r/12,$days/365*12)-1),'yearly'=>$principal*(pow(1+$r,$days/365)-1),default=>$principal*$r*$days/365};$gross=round($gross,2);$tax=round($gross*($d['tax_percent']??0)/100.0,2);$net=round($gross-$tax-($d['fees']??0),2);return ['days'=>$days,'gross_interest'=>$gross,'tax'=>$tax,'net_interest'=>$net,'maturity'=>round($principal+$net,2),'annualized_percent'=>round((pow(max(0,($principal+$net)/$principal),365/$days)-1)*100,3)];}
}
